select '2026-2027','MESEM','MESEM',a.grade_level,c.id,'uygulama',array[a.h],1,true,'https://meslek.meb.gov.tr/upload/cop11_mem/2021_tekstil_mem_cop.pdf','2021-33 yaşayan MESEM Tekstil Teknolojisi çizelgesi; parantezli saatler DIPLOMA fark dersidir.',true,now(),now(),'Tekstil Teknolojisi',br.branch_name,'{"enterpriseDays":4,"enterpriseHoursPerDay":8}'::jsonb,'2021-33',br.page,'HAFTALIK DERS ÇİZELGESİ',1,false,v.schedule_variant
from a join course_catalog c on c.name=a.name cross join br cross join v
where not exists(select 1 from official_course_schedule_catalog x where x.active and x.effective_academic_year='2026-2027' and x.school_type='MESEM' and x.field_name='Tekstil Teknolojisi' and x.branch_name=br.branch_name and x.grade_level=a.grade_level and x.schedule_variant=v.schedule_variant and x.course_id=c.id);

