select '2026-2027','MESEM','MESEM',d.grade_level,c.id,'uygulama',array[d.h],1,true,'https://meslek.meb.gov.tr/upload/cop11_mem/2021_tekstil_mem_cop.pdf','2021-33 yaşayan MESEM Tekstil Teknolojisi çizelgesi; parantezli saatler DIPLOMA fark dersidir.',true,now(),now(),'Tekstil Teknolojisi',d.branch_name,'{"enterpriseDays":4,"enterpriseHoursPerDay":8}'::jsonb,'2021-33',d.page,'HAFTALIK DERS ÇİZELGESİ',1,false,v.schedule_variant
